// Headless verification of the FLIP solver embedded in water-simulation.html
import { readFileSync } from "fs";

const html = readFileSync(new URL("./water-simulation.html", import.meta.url), "utf8");
const start = html.indexOf("const FLUID");
const end = html.indexOf("const SPLAT_VS");
if (start < 0 || end < 0) throw new Error("could not extract physics section");
const physicsSrc = html.slice(start, end);
const make = new Function(physicsSrc + "\nreturn FlipFluid;");
const FlipFluid = make();

const fluid = new FlipFluid(3.0 * 1.77, 3.0, 64, 30000);
fluid.fillDamBreak();
const N0 = fluid.numParticles;
console.log(`grid ${fluid.fNumX}x${fluid.fNumY}, h=${fluid.h.toFixed(4)} m, particles=${N0}`);

const obs = { active: false, x: 0, y: 0, vx: 0, vy: 0, r: 0.3 };
const dt = 1 / 120;

function stats() {
  let maxSpeed = 0, ke = 0, minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9, bad = 0;
  for (let i = 0; i < fluid.numParticles; i++) {
    const x = fluid.pos[2 * i], y = fluid.pos[2 * i + 1];
    const vx = fluid.vel[2 * i], vy = fluid.vel[2 * i + 1];
    if (!isFinite(x) || !isFinite(y) || !isFinite(vx) || !isFinite(vy)) bad++;
    const s2 = vx * vx + vy * vy;
    ke += 0.5 * s2;
    maxSpeed = Math.max(maxSpeed, Math.sqrt(s2));
    minX = Math.min(minX, x); maxX = Math.max(maxX, x);
    minY = Math.min(minY, y); maxY = Math.max(maxY, y);
  }
  return { maxSpeed, ke: ke / fluid.numParticles, minX, maxX, minY, maxY, bad };
}

// 12 simulated seconds = 1440 substeps; dam break should collapse then settle
const t0 = Date.now();
let steps = 0;
for (let f = 0; f < 720; f++) {
  // stir with the obstacle between t=4s and t=5s to exercise that code path
  if (f >= 240 && f < 300) {
    obs.active = true;
    obs.x = fluid.worldW * 0.5 + 0.8 * Math.sin(f * 0.2);
    obs.y = 0.8;
    obs.vx = 0.8 * 0.2 * Math.cos(f * 0.2) * 60;
    obs.vy = 0;
  } else obs.active = false;
  for (let s = 0; s < 2; s++) { fluid.simulate(dt, -9.81, 0.9, 30, 2, 1.9, obs); steps++; }
  if (f % 120 === 0 || f === 719) {
    const st = stats();
    console.log(
      `t=${(f / 60).toFixed(1).padStart(5)}s  maxSpeed=${st.maxSpeed.toFixed(2).padStart(6)} m/s  ` +
      `KE/m=${st.ke.toFixed(3).padStart(7)}  y∈[${st.minY.toFixed(3)},${st.maxY.toFixed(3)}]  ` +
      `x∈[${st.minX.toFixed(3)},${st.maxX.toFixed(3)}]  NaN=${st.bad}`
    );
  }
}
const ms = Date.now() - t0;
console.log(`\n${steps} substeps in ${ms} ms -> ${(ms / (steps / 2)).toFixed(2)} ms per frame (2 substeps)`);

const st = stats();
const h = fluid.h, r = fluid.particleRadius, eps = 1e-6;
const inBounds = st.minX >= h + r - eps && st.maxX <= fluid.worldW - h - r + eps &&
                 st.minY >= h + r - eps && st.maxY <= fluid.worldH - h - r + eps;
console.log(`particles conserved: ${fluid.numParticles === N0} (${fluid.numParticles})`);
console.log(`all inside tank walls: ${inBounds}`);
console.log(`no NaN/Inf: ${st.bad === 0}`);
console.log(`settled (KE/m < 0.05 J/kg after 12 s): ${st.ke < 0.05} (KE/m=${st.ke.toFixed(4)})`);

// fill-level check: settled water level should match conserved volume
let levels = [];
for (let i = 0; i < fluid.numParticles; i++) levels.push(fluid.pos[2 * i + 1]);
levels.sort((a, b) => a - b);
const top = levels[Math.floor(levels.length * 0.999)];
const expectedArea = N0 * (2 * r) * (Math.sqrt(3) * r);  // hex-packed particle area
const interiorW = fluid.worldW - 2 * h;
const expectedLevel = h + expectedArea / interiorW;
console.log(`settled surface y=${top.toFixed(3)} m vs volume-conservation prediction ${expectedLevel.toFixed(3)} m`);

const pass = fluid.numParticles === N0 && inBounds && st.bad === 0 && st.ke < 0.05 &&
             Math.abs(top - expectedLevel) < 0.15;
console.log(pass ? "\nALL CHECKS PASSED" : "\nCHECKS FAILED");
process.exit(pass ? 0 : 1);
